/* Parser validation and bounds; no external image service. JPEG/PNG are generated by the local cropper. */
globalThis.FMZMemberVerifyImage=async(bytes,mime,PDFLib)=>{
 bytes=Uint8Array.from(bytes); // Parsers must receive the exact bytes, without a pooled Buffer offset.
 const doc=await PDFLib.PDFDocument.create();let image;
 if(mime==='image/jpeg')image=await doc.embedJpg(bytes);else if(mime==='image/png')image=await doc.embedPng(bytes);else throw Error('Gebruik JPEG of PNG na lokale conversie.');
 if(!Number.isInteger(image.width)||!Number.isInteger(image.height)||image.width<1||image.height<1||image.width>4096||image.height>4096||image.width*image.height>16000000)throw Error('Afbeeldingsafmetingen niet toegestaan');
 return {width:image.width,height:image.height};
};
